function loneSensor(readings) {
    for (let i = 0; i < readings.length; i++) {
        let count = 0;
        for (const reading of readings)
            if (reading === readings[i])
                count++;
        if (count === 1)
            return readings[i];
    }
    return readings[0];
}

function loneSensor(readings) {
    let lone = 0;
    for (const reading of readings)
        lone ^= reading;
    return lone;
}
